import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const group = new Group();
  group.name = 'pricing-card-3-label';

  const paperHex = '#e8ecf2';
  const accentHex = '#ff2a38';

  // --- Engineered gradient backdrop panel ---
  const panelGeo = new PlaneGeometry(1.4, 0.4);
  const panelMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.93,
  });

  panelMat.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, uv().y)
  );

  const panel = new Mesh(panelGeo, panelMat);
  panel.position.z = -0.001;
  group.add(panel);

  // --- Accent underline ---
  const lineGeo = new PlaneGeometry(1.4, 0.012);
  const lineMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.65,
  });
  lineMat.color = new Color(accentHex);
  const line = new Mesh(lineGeo, lineMat);
  line.position.y = -0.158;
  line.position.z = 0.001;
  group.add(line);

  // --- Text headline ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem =
    items.find((i) => i.role === 'headline') ||
    (items.length > 0 ? items[0] : null);

  let textMeshRef = null;
  if (headlineItem) {
    const fontSize = headlineItem.typography?.fontSize || 39;
    const contentStr =
      typeof headlineItem.text === 'string'
        ? headlineItem.text
        : String(headlineItem.text ?? '');
    textMeshRef = ctx.fontAtlas.createText(contentStr, {
      fontSize,
      color: paperHex,
      align: 'center',
    });
    textMeshRef.position.z = 0.012;
    group.add(textMeshRef);
  }

  // --- Optional subtle image overlay ---
  let overlayMesh = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (THREE.SRGBColorSpace) {
        try {
          tex.colorSpace = THREE.SRGBColorSpace;
        } catch (e) {}
      }
      const overlayGeo = new PlaneGeometry(1.4, 0.4);
      const overlayMat = new MeshBasicNodeMaterial({
        transparent: true,
        opacity: 0.1,
      });
      overlayMat.map = tex;
      overlayMat.needsUpdate = true;
      overlayMesh = new Mesh(overlayGeo, overlayMat);
      overlayMesh.position.z = 0.004;
      group.add(overlayMesh);
    });
  }

  // --- Handlers: non-interactive label ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    panelGeo.dispose();
    panelMat.dispose();
    lineGeo.dispose();
    lineMat.dispose();
    if (overlayMesh) {
      overlayMesh.geometry.dispose();
      overlayMesh.material.dispose();
    }
    if (textMeshRef) {
      textMeshRef.traverse((child) => {
        if (child.geometry && child.geometry.dispose) {
          child.geometry.dispose();
        }
        if (child.material && child.material.dispose) {
          child.material.dispose();
        }
      });
    }
  };

  return group;
}
